intro.snippet:
class Node {
public:
    int val;
    Node* next;
    Node(int val){
        this->val = val;
        this->next = NULL;
    }
};

Node* head = new Node(10);
Node* a = new Node(20);
head->next = a;              // 10 is now coupled to 20
cout << head->next->val;     // prints 20

Node* tmp = head;
while(tmp != NULL){
    cout << tmp->val << endl;
    tmp = tmp->next;
}

